{"source":"import csv
import json
import sys
import re

def normalize_item(name):
    # Collapse all whitespace to single spaces and casefold
    # We use re.sub to replace any whitespace sequence with a single space
    # then strip to remove leading/trailing spaces.
    if not name:
        return ""
    normalized = re.sub(r'\s+','', name).strip().casefold()
    return normalized

def main():
    if len(sys.argv) < 2:
        return

    filename = sys.argv[1]
    counts = {}

    try:
        with open(filename, mode='r', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                raw_name = row.get('item', '')
                raw_quantity = row.get('quantity', '')

                norm_name = normalize_item(raw_name)

                if not norm_name:
                    continue

                if raw_quantity.strip() == "":
                    quantity = 1
                else:
                    try:
                        quantity = int(raw_quantity.strip())
                    except ValueError:
                        # The problem states they are non-negative base-10 integers.
                        # However, we'll handle unexpected cases if necessary.
                        continue

                counts[norm_name] = counts.get(norm_name, 0) + quantity
    except FileNotFoundError:
        return

    # Sort by normalized item name
    sorted_items = sorted(counts.items())

    output = []
    for item_name, qty in sorted_items:
        output.append({"item": item_name, "quantity": qty})

    print(json.dumps(output))

if __name__ == "__main__":
    main()
